   "hi": "$\\sqrt{36} = 6$, एक साधारण गिनती की संख्या। root का sign *irrational* कहने को उकसाता है — पर classify करने से **पहले** हमेशा सरल कीजिए। मूल तभी irrational होता है जब उसके नीचे की संख्या perfect square न हो।"
